#include "anaiero/sdk/storage_tools.hpp"
#include "christeye/living/durable_registry.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <stdexcept>

using namespace anaiero::sdk;
using namespace anaiero::sdk::evidence;
namespace fs=std::filesystem;
namespace old=christeye::living::durable;
namespace {
void expect(bool condition,const std::string& why){if(!condition)throw std::runtime_error(why);}
void require(Result r,const std::string& why){if(!r)throw std::runtime_error(why+": "+std::string(code_name(r.code))+" "+r.message);}
struct Temporary {fs::path path;explicit Temporary(std::string name){path=fs::temp_directory_path()/("anaiero-migration-"+name+'-'+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(path);}~Temporary(){std::error_code ec;for(const auto& entry:fs::recursive_directory_iterator(path,fs::directory_options::skip_permission_denied,ec))fs::permissions(entry.path(),fs::perms::owner_all,fs::perm_options::add,ec);fs::remove_all(path,ec);}};
std::string read(const fs::path& path){std::ifstream file(path,std::ios::binary);expect(static_cast<bool>(file),"read fixture");return {std::istreambuf_iterator<char>(file),{}};}
void write(const fs::path& path,std::string_view bytes){std::ofstream file(path,std::ios::binary|std::ios::trunc);file.write(bytes.data(),static_cast<std::streamsize>(bytes.size()));expect(static_cast<bool>(file),"write fixture");}
std::map<std::string,Digest> fingerprints(const fs::path& path){std::map<std::string,Digest> result;for(const auto& entry:fs::recursive_directory_iterator(path))if(entry.is_regular_file())result.emplace(entry.path().lexically_relative(path).generic_string(),sha256(read(entry.path())));return result;}
std::unique_ptr<ICommitStore> open(const fs::path& path){std::unique_ptr<ICommitStore> result;require(open_native_store(path.string(),{},result),"open migration result");return result;}
void legacy_exact_bytes_and_quiescence(){
  Temporary temp("bounded");const auto source=temp.path/"source",destination=temp.path/"destination";old::Registry registry;expect(registry.open(source)==old::Code::ok,"open old registry");const auto first=registry.put("original object"),second=registry.put("second object"),opaque=registry.put("opaque unreferenced provenance");expect(first.code==old::Code::ok&&second.code==old::Code::ok&&opaque.code==old::Code::ok,"legacy objects");
  expect(registry.publish("OBSERVATION_RECORDED","source",first.hash,"SIMULATED",7,"clock","producer").code==old::Code::ok,"first occurrence");expect(registry.publish("OBSERVATION_RECORDED","source",second.hash,"INFERRED",7,"clock","producer").code==old::Code::ok,"second occurrence same key");expect(registry.publish("OBSERVATION_RECORDED","source",first.hash,"SIMULATED",7,"clock","producer").code==old::Code::ok&&registry.event_count()==2,"legacy exact duplicate");
  MigrationReport report;expect(migrate_legacy_evidence(source.string(),destination.string(),{},report).code==Code::busy&&!fs::exists(destination),"active legacy writer rejected");registry.close();
  // Existing legacy parsing permits normalized whitespace. Preserve the exact
  // original acknowledged wire, together with its independent event identity.
  auto journal=read(source/"events.log");const auto start=journal.find("event ");expect(start!=std::string::npos,"fixture event line");journal.insert(start,"  ");old::Head head;expect(old::parse_head(read(source/"HEAD"),head),"fixture HEAD");head.offset+=2;write(source/"HEAD",old::sealed_head(head));write(source/"events.log",journal+"uncommitted crash tail\n");const auto original=fingerprints(source);
  require(migrate_legacy_evidence(source.string(),destination.string(),{},report),"migrate bounded registry");expect(report.activated&&report.source_unchanged&&report.events==2&&report.objects==3,"migration report");expect(fingerprints(source)==original,"original source untouched including uncommitted tail");expect(fingerprints(fs::path(report.backup_directory))==original,"retained snapshot is byte-exact raw source");expect(report.retained_backup_bytes==report.source_bytes&&report.peak_required_bytes>report.target_bytes+report.source_bytes,"separate snapshot footprint disclosed");
  auto store=open(destination);StoredEvent event;const EventKey key{"OBSERVATION_RECORDED","source","clock","producer",7};require(store->find_event(key,event),"new latest tuple");expect(event.event.object_digest==second.hash&&event.event.origin=="INFERRED","distinct generic occurrences preserved");require(store->find_event(key,event,first.hash,"SIMULATED"),"new exact occurrence");StoredRecord wire;require(store->latest("legacy.event","0000000000000001",wire),"raw legacy event record");std::vector<std::string> fields;require(unpack(wire.record.payload,fields,5),"decode legacy provenance");
  old::Event parsed;expect(fields.size()==5&&old::parse_event(fields[4],parsed)&&parsed.hash==fields[2]&&fields[4].starts_with("  event ")&&sha256(fields[4])==fields[3],"exact wire and original legacy hash preserved");
  CommitBatch expire;expire.operation_id="try-expire-opaque";expire.request_digest=sha256(expire.operation_id);expire.expire_blobs={opaque.hash};CommitReceipt receipt;expect(store->commit(expire,receipt).code==Code::conflict,"opaque objects remain individually pinned");const auto root=store->info().root_digest;store.reset();MigrationReport repeated;require(migrate_legacy_evidence(source.string(),destination.string(),{},repeated),"repeat migration");expect(repeated.already_complete&&repeated.destination_root==root,"completed migration retry is idempotent");
  write(source/"new-metadata","new source context");expect(migrate_legacy_evidence(source.string(),destination.string(),{},repeated).code==Code::conflict,"changed source cannot reuse old destination");expect(open(destination)->info().root_digest==root,"conflicting retry leaves destination unchanged");
}
void segmented_archived_history_and_resume(){
  Temporary temp("segmented");const auto source=temp.path/"source",destination=temp.path/"destination";old::Registry registry;expect(registry.open(source,old::StorageOptions::sustained(8))==old::Code::ok,"open sustained source");std::string last;
  for(unsigned i=0;i<25;++i){const auto object=registry.put("historical-object-"+std::to_string(i));expect(object.code==old::Code::ok,"put sustained object");last=object.hash;expect(registry.publish("OBSERVATION_RECORDED","retired-source",last,"SIMULATED",i,"clock","producer").code==old::Code::ok,"publish sustained occurrence");}
  const std::vector<std::string> references{last};expect(registry.save_replay_checkpoint("legacy projection",references),"old replay root");expect(registry.archive_ready()==old::Code::ok,"archive historical segments");old::ArchiveStats archived;expect(registry.collect_objects(archived)==old::Code::ok,"archive historical objects");const auto opaque=registry.put("uninterpreted model provenance");expect(opaque.code==old::Code::ok,"opaque post-archive object");expect(registry.capacity().archived_segments!=0&&registry.events().size()<25,"source tail does not contain all history");registry.close();const auto original=fingerprints(source);
  StoreOptions small;small.maximum_bytes=512U*1024U;MigrationReport failed;const auto cut=migrate_legacy_evidence(source.string(),destination.string(),small,failed);expect(cut.code==Code::capacity&&!fs::exists(destination)&&fs::exists(temp.path/"destination.migration"),"quota failure keeps destination unpublished and resumable staging");expect(fingerprints(source)==original,"failed migration leaves source byte-exact");
  MigrationReport report;require(migrate_legacy_evidence(source.string(),destination.string(),{},report),"resume archived migration");expect(report.resumed&&report.events==25&&report.objects>=27,"all archived history and opaque objects migrated");auto store=open(destination);StoredEvent event;require(store->find_event({"OBSERVATION_RECORDED","retired-source","clock","producer",0},event),"first archived occurrence indexed");Bytes bytes;require(store->get_blob(event.event.object_digest,bytes),"archived bytes in new CAS");expect(bytes=="historical-object-0","correct oldest historical payload");require(store->get_blob(opaque.hash,bytes),"opaque orphan retained");AuditReport audit;require(store->audit(audit),"full migrated history audit");
}
void fail_closed_source_and_destination(){
  Temporary temp("reject");const auto source=temp.path/"source";old::Registry registry;expect(registry.open(source)==old::Code::ok,"open corruption fixture");const auto bad=registry.put("unreferenced corrupted object");expect(bad.code==old::Code::ok,"create opaque corruption fixture");registry.close();write(source/"objects"/bad.hash,"different bytes");const auto original=fingerprints(source);MigrationReport report;const auto result=migrate_legacy_evidence(source.string(),(temp.path/"bad-target").string(),{},report);expect(result.code==Code::corrupt&&!fs::exists(temp.path/"bad-target"),"corrupt unreferenced CAS cannot activate");expect(fingerprints(source)==original,"rejected source remains untouched");
  const auto occupied=temp.path/"occupied";fs::create_directories(occupied);expect(migrate_legacy_evidence(source.string(),occupied.string(),{},report).code==Code::conflict&&!fs::exists(occupied/"ROOT"),"unrelated existing destination is not initialized or replaced");
  expect(migrate_legacy_evidence(source.string(),(source/"nested").string(),{},report).code==Code::invalid&&!fs::exists(source/"nested"),"nested migration cannot modify source");
}
}
int main(){try{legacy_exact_bytes_and_quiescence();segmented_archived_history_and_resume();fail_closed_source_and_destination();std::cout<<"legacy evidence migration: quiescence, exact bytes, archived history, pinned provenance, resumable quota failure and atomic activation passed\n";return 0;}catch(const std::exception& e){std::cerr<<"migration failure: "<<e.what()<<'\n';return 1;}}
